def is_magic_square(m):
    n = len(m)
    if n == 0:
        return False
    for row in m:
        if len(row) != n:
            return False
    values = [v for row in m for v in row]
    if len(set(values)) != len(values):
        return False
    if any(v <= 0 for v in values):
        return False
    target = sum(m[0])
    for row in m:
        if sum(row) != target:
            return False
    for j in range(n):
        if sum(m[i][j] for i in range(n)) != target:
            return False
    if sum(m[i][i] for i in range(n)) != target:
        return False
    if sum(m[i][n - 1 - i] for i in range(n)) != target:
        return False
    return True

def is_permutation_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for row in m:
        if any(v not in (0, 1) for v in row):
            return False
        if sum(row) != 1:
            return False
    for j in range(n):
        if sum(m[i][j] for i in range(n)) != 1:
            return False
    return True

def is_identity_matrix(m):
    n = len(m)
    for row in m:
        if len(row) != n:
            return False
    for i in range(n):
        for j in range(n):
            expected = 1 if i == j else 0
            if m[i][j] != expected:
                return False
    return True

def is_valid_tic_tac_toe_counts(board):
    if len(board) != 3:
        return False
    for row in board:
        if len(row) != 3:
            return False
    x_count = o_count = 0
    for row in board:
        for c in row:
            if c == 'X':
                x_count += 1
            elif c == 'O':
                o_count += 1
            elif c != ' ':
                return False
    return x_count == o_count or x_count == o_count + 1

def is_valid_percentage_string(s):
    if not s.endswith('%') or len(s) < 2:
        return False
    num_part = s[:-1]
    if not all(c.isdigit() or c == '.' for c in num_part):
        return False
    if num_part.count('.') > 1:
        return False
    if num_part.startswith('.') or num_part.endswith('.'):
        return False
    value = float(num_part)
    return 0 <= value <= 100

def is_valid_currency_amount(s):
    if not s.startswith('$'):
        return False
    body = s[1:]
    if '.' in body:
        int_part, _, frac_part = body.partition('.')
        if len(frac_part) != 2 or not frac_part.isdigit():
            return False
    else:
        int_part = body
    if not int_part:
        return False
    groups = int_part.split(',')
    if len(groups) == 1:
        return groups[0].isdigit() and 1 <= len(groups[0]) <= 3
    if not groups[0].isdigit() or not (1 <= len(groups[0]) <= 3):
        return False
    for g in groups[1:]:
        if len(g) != 3 or not g.isdigit():
            return False
    return True

def is_valid_temperature_reading(s):
    if len(s) < 2:
        return False
    unit = s[-1]
    if unit not in ('C', 'F'):
        return False
    num_part = s[:-1]
    if not num_part:
        return False
    idx = 1 if num_part[0] in '+-' else 0
    rest = num_part[idx:]
    if not rest or rest.startswith('.') or rest.endswith('.'):
        return False
    if rest.count('.') > 1:
        return False
    if not rest.replace('.', '').isdigit():
        return False
    return True

def is_valid_scientific_notation(s):
    import re
    return re.fullmatch(r'[+-]?\d+(\.\d+)?[eE][+-]?\d+', s) is not None

def is_valid_fraction_string(s):
    if s.count('/') != 1:
        return False
    a, b = s.split('/')
    if not a or not b:
        return False
    a_body = a[1:] if a[0] == '-' else a
    if not a_body.isdigit():
        return False
    if len(a_body) > 1 and a_body[0] == '0':
        return False
    if not b.isdigit():
        return False
    if b == '0' or (len(b) > 1 and b[0] == '0'):
        return False
    return True
